class TrieNode:
    def __init__(self):
        self.children = {}          # char -> TrieNode.
        self.is_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):         # O(L).
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, TrieNode())
        node.is_word = True

    def _find(self, prefix):        # O(L) to reach the prefix node.
        node = self.root
        for ch in prefix:
            node = node.children.get(ch)
            if node is None:
                return None
        return node

    def starts_with(self, prefix):  # O(L + size of the answer).
        node, out = self._find(prefix), []
        def collect(n, path):
            if n.is_word:
                out.append(prefix + path)
            for ch in sorted(n.children):
                collect(n.children[ch], path + ch)
        if node:
            collect(node, "")
        return out
